// Bundles migrations/*.sql into src/migrations.generated.js so the Worker can apply any
// pending migrations itself on its first request after a deploy (see src/lib/migrate.js).
// Runs as part of `npm run build` and `npm test`; `node scripts/migrations.mjs --check`
// exits non-zero when the generated file is out of date.
import { readFileSync, readdirSync, writeFileSync, existsSync } from 'node:fs'
const dir = new URL('../migrations/', import.meta.url)
const out = new URL('../src/migrations.generated.js', import.meta.url)
const files = readdirSync(dir).filter(f => /^\d{4}_[\w-]+\.sql$/.test(f)).sort()
const entries = files.map(name => `  { name: ${JSON.stringify(name)}, sql: ${JSON.stringify(readFileSync(new URL(name, dir), 'utf8'))} },`)
const source = `// Generated by scripts/migrations.mjs from migrations/*.sql. Do not edit by hand.\nexport const MIGRATIONS = [\n${entries.join('\n')}\n]\n`
if (process.argv.includes('--check')) {
  if (!existsSync(out) || readFileSync(out, 'utf8') !== source) { console.error('src/migrations.generated.js is out of date: run node scripts/migrations.mjs'); process.exit(1) }
} else if (!existsSync(out) || readFileSync(out, 'utf8') !== source) {
  writeFileSync(out, source)
  console.log(`Bundled ${files.length} migrations into src/migrations.generated.js`)
}
